package database

import "context"

// CheckpointWAL truncates the write-ahead log after the expiry worker deletes
// content. It is not generated by sqlc because PRAGMA statements are outside
// its query model. A busy database returns an error here; the worker retries
// on its next tick.
func (q *Queries) CheckpointWAL(ctx context.Context) error {
	_, err := q.db.ExecContext(ctx, "PRAGMA wal_checkpoint(TRUNCATE)")
	return err
}
